// Ingestion function (Node.js)
const ajv = new Ajv();
let schemaCache = new Map();
async function getSchemaForTenant(tenantId){
  if(schemaCache.has(tenantId)) return schemaCache.get(tenantId);
  const cfg = await AppConfigClient.getConfigurationSetting({key: `schema:${tenantId}`});
  const schema = JSON.parse(cfg.value);
  schemaCache.set(tenantId, schema);
  setTimeout(() => schemaCache.delete(tenantId), 60_000);
  return schema;
}
async function validateAndRoute(msg){
  const tenantId = msg.tenantId;
  const schema = await getSchemaForTenant(tenantId);
  const validate = ajv.compile(schema);
  const valid = validate(msg.payload);
  if(!valid){ await DLQ.push({tenantId, msg, errors: validate.errors}); return; }
  await CosmosDB.upsert('events', tenantId, msg.payload, {dedupId: msg.id});
}
```

